import javax.inject.Inject;
import java.awt.*;
import java.util.Set;

public class ItemOverlays extends WidgetItemOverlay {
    private static final Set<Integer> ESSENCE_IDS = ImmutableSet.of(
            ItemID.BLANKRUNE_HIGH,
            ItemID.BLANKRUNE_DAEYALT
    );

    private static final Set<Integer> STAMINA_IDS = ImmutableSet.of(
            ItemID._1DOSESTAMINA,
            ItemID._2DOSESTAMINA,
            ItemID._3DOSESTAMINA,
            ItemID._4DOSESTAMINA,
            ItemID._1DOSE2STAMINA,
            ItemID._2DOSE2STAMINA,
            ItemID._3DOSE2STAMINA,
            ItemID._4DOSE2STAMINA,
            ItemID.BRUTAL_1DOSESTAMINA,
            ItemID.BRUTAL_2DOSESTAMINA
    );

    private final Client client;
    private final ZMIOverlaysPlugin plugin;
    private final ZMIOverlaysConfig config;
    private final GraphicsUtils graphicsUtils;
    private final PouchUtils pouchUtils;

    private boolean hasStamina = false;

    @Inject
    private ItemOverlays(Client client, ZMIOverlaysPlugin plugin, ZMIOverlaysConfig config, GraphicsUtils graphicsUtils, PouchUtils pouchUtils)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.graphicsUtils = graphicsUtils;
        this.pouchUtils = pouchUtils;

        showOnBank();
        showOnInventory();
        setPriority(2f);
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem) {
        if (plugin.outsideOuraniaArea())
            return;

        var pouch = Pouch.getByItemId(itemId);
        if (pouch != null)
        {
            if (!config.pouchShow())
                return;

            var interfaceID = WidgetUtil.componentToInterface(widgetItem.getWidget().getId());
            if (interfaceID != InterfaceID.INVENTORY)
                return;

            var empty = pouchUtils.getPouchContents(pouch) == 0;
            graphicsUtils.renderBox(graphics, widgetItem, empty ? config.pouchEmptyColour() : config.pouchColour());

            return;
        }

        if (ESSENCE_IDS.contains(itemId))
        {
            if (!config.essenceShow())
                return;

            var interfaceID = WidgetUtil.componentToInterface(widgetItem.getWidget().getId());
            if (interfaceID != InterfaceID.BANKMAIN)
                return;

            graphicsUtils.renderBox(graphics, widgetItem, config.essenceColour());

            return;
        }

        if (STAMINA_IDS.contains(itemId))
        {
            if (!config.staminaShow())
                return;

            if (hasStamina)
                return;

            if (client.getEnergy() / 100 > config.staminaThreshold())
                return;

            graphicsUtils.renderBox(graphics, widgetItem, config.staminaColour());

            return;
        }

        var food = config.foodShow();
        if (food.getId() == itemId)
        {
            var currentHealth = client.getBoostedSkillLevel(Skill.HITPOINTS);
            var maxHealth = client.getRealSkillLevel(Skill.HITPOINTS);

            if ((maxHealth - currentHealth) > food.getHeals())
                graphicsUtils.renderBox(graphics, widgetItem, config.foodColour());
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        if (event.getVarbitId() != VarbitID.STAMINA_ACTIVE)
            return;

        hasStamina = event.getValue() != 0;
    }
}

package org.zhbot.zmi_overlays;

import com.google.inject.Provides;
import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.WorldChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.WorldService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;
import org.zhbot.zmi_overlays.enums.Pouch;
import org.zhbot.zmi_overlays.enums.Rune;
import org.zhbot.zmi_overlays.overlays.ItemOverlays;
import org.zhbot.zmi_overlays.overlays.Infobox;
import org.zhbot.zmi_overlays.overlays.SpellOverlays;
import org.zhbot.zmi_overlays.overlays.WorldOverlays;
import org.zhbot.zmi_overlays.utils.PouchUtils;
import org.zhbot.zmi_overlays.utils.TextUtils;

@Slf4j
@PluginDescriptor(
	name = "ZMI Overlays"
)
public class ZMIOverlaysPlugin extends Plugin
{
	private static final int OURANIA_CAVE_REGION_ID = 12119;
	private static final int OURANIA_SURFACE_REGION_ID = 9778;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private WorldService worldService;

	@Inject
	private ZMIOverlaysConfig config;

	@Inject
	private PouchUtils pouchUtils;

	@Inject
	private TextUtils textUtils;

	@Inject
	private WorldOverlays worldOverlays;

	@Inject
	private ItemOverlays itemOverlays;

	@Inject
	private SpellOverlays spellOverlays;

	@Inject
	private Infobox infobox;

	private boolean zmiWorld = false;
	private boolean inOuraniaArea = false;

	@Override
	protected void startUp() throws Exception
	{
		eventBus.register(pouchUtils);

		overlayManager.add(worldOverlays);
		eventBus.register(worldOverlays);

		overlayManager.add(itemOverlays);
		eventBus.register(itemOverlays);

		overlayManager.add(spellOverlays);
		eventBus.register(spellOverlays);

		overlayManager.add(infobox);
		eventBus.register(infobox);

		worldOverlays.startup();
		infobox.startup();

		clientThread.invoke(this::checkZMIWorld);
	}

	@Override
	protected void shutDown() throws Exception
	{
		pouchUtils.cleanup();
		worldOverlays.cleanup();
		infobox.cleanup();

		eventBus.unregister(pouchUtils);

		overlayManager.remove(worldOverlays);
		eventBus.unregister(worldOverlays);

		overlayManager.remove(itemOverlays);
		eventBus.unregister(itemOverlays);

		overlayManager.remove(spellOverlays);
		eventBus.unregister(spellOverlays);

		overlayManager.remove(infobox);
		eventBus.unregister(infobox);
	}

	@Provides
	ZMIOverlaysConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ZMIOverlaysConfig.class);
	}

	@Subscribe
	public void onWorldChanged(WorldChanged event)
	{
		checkZMIWorld();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		var localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			inOuraniaArea = false;
			return;
		}

		var regionID = localPlayer.getWorldLocation().getRegionID();

		inOuraniaArea = regionID == OURANIA_CAVE_REGION_ID || regionID == OURANIA_SURFACE_REGION_ID;
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		if (outsideOuraniaArea())
			return;

		var menu = client.getMenu();

		var entries = menu.getMenuEntries();
		for (var entry : entries)
		{
			var target = textUtils.Clean(entry.getTarget());
			var pouch = Pouch.getByName(target);
			if (pouch == null)
				continue;

			var option = textUtils.Clean(entry.getOption());
			switch (option)
			{
				case "Empty":
					if (!isBankOpen())
						continue;
				case "Empty-to-inventory":
					if (!config.emptyDisable())
						continue;

					menu.removeMenuEntry(entry);
					break;
				case "Fill":
					if (!config.fillDisable())
						continue;

					if (isBankOpen())
						continue;

					menu.removeMenuEntry(entry);
					break;
			}
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (outsideOuraniaArea())
			return;

		var option = textUtils.Clean(event.getOption());
		if (!option.equals("Choose"))
			return;

		var target = textUtils.Clean(event.getTarget());
		var rune = Rune.getByName(target);
		if (rune == null)
			return;

		if (!config.chooseRuneDisable().contains(rune))
			return;

		client.getMenu().removeMenuEntry(event.getMenuEntry());
	}

	public boolean outsideOuraniaArea()
	{
		return (config.ZMIWorldsOnly() && !zmiWorld) || !inOuraniaArea;
	}

	private boolean isBankOpen()
	{
		var bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		return bank != null && !bank.isHidden();
	}

	private void checkZMIWorld()
	{
		zmiWorld = false;

		var worlds = worldService.getWorlds();
		if (worlds == null)
			return;

		var world = worlds.findWorld(client.getWorld());
		if (world == null)
			return;

		zmiWorld = world.getActivity().equalsIgnoreCase("Ourania Altar");
	}
}
